CREATE TABLE public."COMPONENTLICENSES" (
    "ID" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "COMPONENTID" bigint NOT NULL,
    "LICENSE_ID" bigint,
    "LICENSE" character varying(255),
    "LICENSE_EXPRESSION" text,
    "LICENSE_URL" character varying(255),
    "ORDINALITY" bigint NOT NULL CHECK ("ORDINALITY" > 0),
    "CONCLUDED" boolean DEFAULT false NOT NULL
);

INSERT INTO public."COMPONENTLICENSES" (
    "COMPONENTID",
    "LICENSE_ID",
    "LICENSE",
    "LICENSE_EXPRESSION",
    "LICENSE_URL",
    "ORDINALITY",
    "CONCLUDED"
) SELECT "ID", "LICENSE_ID", "LICENSE", "LICENSE_EXPRESSION", "LICENSE_URL", 1, false FROM public."COMPONENT";

ALTER TABLE ONLY public."COMPONENTLICENSES"
    ADD CONSTRAINT "COMPONENTLICENSES_FK1" FOREIGN KEY ("COMPONENTID") REFERENCES public."COMPONENT"("ID") DEFERRABLE INITIALLY DEFERRED;

ALTER TABLE ONLY public."COMPONENTLICENSES"
    ADD CONSTRAINT "COMPONENTLICENSES_FK2" FOREIGN KEY ("LICENSE_ID") REFERENCES public."LICENSE"("ID") DEFERRABLE INITIALLY DEFERRED;

ALTER TABLE ONLY public."COMPONENTLICENSES"
    ADD CONSTRAINT "COMPONENTLICENSES_CK"
    CHECK (
        "LICENSE_ID" IS NOT NULL
        OR "LICENSE_EXPRESSION" IS NOT NULL
    );

CREATE UNIQUE INDEX "COMPONENTLICENSES_ID_UQ"
    ON "COMPONENTLICENSES" ("COMPONENTID", "LICENSE_ID")
    WHERE "LICENSE_ID" IS NOT NULL;
 
CREATE UNIQUE INDEX "COMPONENTLICENSES_EXP_UQ"
    ON "COMPONENTLICENSES" ("COMPONENTID", "LICENSE_EXPRESSION")
    WHERE "LICENSE_EXPRESSION" IS NOT NULL;

ALTER TABLE public."COMPONENT" 
    DROP CONSTRAINT "COMPONENT_LICENSE_FK",
    DROP COLUMN "LICENSE_ID",
    DROP COLUMN "LICENSE",
    DROP COLUMN "LICENSE_EXPRESSION",
    DROP COLUMN "LICENSE_URL";

CREATE INDEX "COMPONENTLICENSES_COMPONENT_ORDINALITY_IDX"
    ON public."COMPONENTLICENSES" ("COMPONENTID", "ORDINALITY");
